TIMELINE_ESM = '// Plan timeline: drag modules along a quarterly-scaled monthly timeline and edit their parameters.\n// Vanilla ES module, no build step. The Python side validates the plan, so this\n// file only makes edits and does not enforce the full schema.\n\nconst PX = 6; // pixels per month (a quarter is 3 * PX)\nconst LABEL_W = 240;\n\nconst ACCOUNT_TYPES = [\n  "cash", "taxable", "traditional_401k", "roth_401k", "traditional_ira",\n  "roth_ira", "hsa", "real_estate",\n];\nconst EVENT_KINDS = [\n  "one_time_income", "one_time_expense", "lump_sum_debt_payment",\n  "lump_sum_asset_contribution", "asset_withdrawal",\n];\nconst PCT_KEYS = new Set([\n  "apr", "annual_return", "inflation", "cash_return", "annual_raise", "surplus_to_debt",\n]);\n\n// window: active from start to end. account: opens at start, persists.\n// point: a single month. changes: term changes listed on the account.\nconst KINDS = {\n  strategies: {\n    title: "Debt strategies", window: true,\n    fields: [\n      { k: "label", t: "text" },\n      { k: "debt_strategy", t: "select", options: ["avalanche", "snowball", "fixed"] },\n      { k: "debt_priority", t: "list", opt: true },\n      { k: "surplus_to_debt", t: "pct" },\n    ],\n  },\n  assumptions: {\n    title: "Assumptions", window: true,\n    fields: [\n      { k: "label", t: "text" },\n      { k: "inflation", t: "pct", opt: true },\n      { k: "cash_return", t: "pct", opt: true },\n    ],\n  },\n  incomes: {\n    title: "Incomes", window: true,\n    fields: [\n      { k: "label", t: "text" },\n      { k: "owner", t: "text", opt: true },\n      { k: "gross_annual", t: "money" },\n      { k: "annual_raise", t: "pct" },\n      { k: "pay_frequency", t: "select", options: ["monthly", "biweekly", "semimonthly"] },\n    ],\n  },\n  expenses: {\n    title: "Expenses", window: true,\n    fields: [\n      { k: "label", t: "text" },\n      { k: "category", t: "text" },\n      { k: "monthly", t: "money" },\n      { k: "inflation_linked", t: "bool" },\n    ],\n  },\n  debts: {\n    title: "Debts", account: true, changes: ["apr", "minimum_payment"],\n    fields: [\n      { k: "label", t: "text" },\n      { k: "owner", t: "text", opt: true },\n      { k: "opening_balance", t: "money" },\n      { k: "apr", t: "pct" },\n      { k: "minimum_payment", t: "money" },\n      { k: "convention", t: "select", options: ["monthly_apr", "daily_apr"] },\n    ],\n  },\n  assets: {\n    title: "Assets", account: true, changes: ["annual_return", "monthly_contribution"],\n    fields: [\n      { k: "label", t: "text" },\n      { k: "owner", t: "text", opt: true },\n      { k: "account_type", t: "select", options: ACCOUNT_TYPES },\n      { k: "opening_balance", t: "money" },\n      { k: "annual_return", t: "pct" },\n      { k: "monthly_contribution", t: "money" },\n    ],\n  },\n  events: {\n    title: "Events", point: true,\n    fields: [\n      { k: "label", t: "text" },\n      { k: "kind", t: "select", options: EVENT_KINDS },\n      { k: "amount", t: "money" },\n      { k: "target_id", t: "text", opt: true },\n    ],\n  },\n};\n\n// Editable type for each change field (used by the change editor).\nconst CHANGE_TYPES = {\n  apr: "pct", minimum_payment: "money", annual_return: "pct", monthly_contribution: "money",\n};\n\n// --- month helpers ---------------------------------------------------------\n\nfunction idx(m) {\n  const [y, mo] = m.split("-").map(Number);\n  return y * 12 + (mo - 1);\n}\n\nfunction fmt(i) {\n  return `${Math.floor(i / 12)}-${String(((i % 12) + 12) % 12 + 1).padStart(2, "0")}`;\n}\n\n// Quarter starts are months with idx % 3 == 0 (Jan, Apr, Jul, Oct).\n// Quarter ends are months with idx % 3 == 2 (Mar, Jun, Sep, Dec).\nfunction snapStart(i) {\n  return Math.round(i / 3) * 3;\n}\n\nfunction snapEnd(i) {\n  return Math.round((i - 2) / 3) * 3 + 2;\n}\n\nfunction findItem(plan, kind, id) {\n  return (plan[kind] || []).find((x) => x.id === id);\n}\n\nfunction viewRange(plan) {\n  const last = plan.eras[plan.eras.length - 1];\n  let hi = last.end ? idx(last.end) : idx(plan.start) + 480;\n  for (const k of ["incomes", "expenses", "strategies", "assumptions"]) {\n    for (const w of plan[k]) if (w.end) hi = Math.max(hi, idx(w.end));\n  }\n  for (const e of plan.events) hi = Math.max(hi, idx(e.month));\n  for (const k of ["debts", "assets"]) {\n    for (const a of plan[k]) for (const c of a.changes || []) hi = Math.max(hi, idx(c.month));\n  }\n  const lo = Math.floor(idx(plan.start) / 12) * 12;\n  return { lo, hi: hi + 12 };\n}\n\n// Drag result for a module. Windows snap to whole quarters: start to a quarter\n// start, end to a quarter end, and never shorter than one quarter. Moves keep the\n// module\'s length. Point events and account openings snap to a quarter start.\nfunction snapSpan(kind, mode, s0, e0, dm) {\n  const cfg = KINDS[kind];\n  if (cfg.point || cfg.account) return { s: snapStart(s0 + dm), en: null };\n  if (mode === "move") {\n    const s = snapStart(s0 + dm);\n    if (e0 === null) return { s, en: null };\n    return { s, en: Math.max(snapEnd(s + (e0 - s0)), s + 2) };\n  }\n  if (mode === "l") {\n    let s = snapStart(s0 + dm);\n    if (e0 !== null) s = Math.min(s, snapStart(e0 - 2));\n    return { s, en: e0 };\n  }\n  // mode "r": move the end edge\n  if (e0 === null) return { s: s0, en: null };\n  return { s: s0, en: Math.max(snapEnd(e0 + dm), snapStart(s0) + 2) };\n}\n\n// --- value formatting --------------------------------------------------------\n\nfunction money(v) {\n  if (v === null || v === undefined) return "-";\n  const a = Math.abs(v);\n  if (a >= 1e6) return `$${(v / 1e6).toFixed(2).replace(/\\.?0+$/, "")}M`;\n  if (a >= 1000) return `$${(v / 1000).toFixed(1).replace(/\\.0$/, "")}k`;\n  return `$${Math.round(v)}`;\n}\n\nfunction pct(v) {\n  if (v === null || v === undefined) return "-";\n  return `${+(v * 100).toFixed(2)}%`;\n}\n\nfunction fieldValue(k, v) {\n  return PCT_KEYS.has(k) ? pct(v) : money(v);\n}\n\n// Short value summary shown on a bar or marker.\nfunction valueText(kind, it) {\n  switch (kind) {\n    case "incomes":\n      return `${money(it.gross_annual)}/yr${it.annual_raise ? ` +${pct(it.annual_raise)}/yr` : ""}`;\n    case "expenses":\n      return `${money(it.monthly)}/mo`;\n    case "debts":\n      return `${money(it.opening_balance)} @ ${pct(it.apr)} · min ${money(it.minimum_payment)}/mo`;\n    case "assets":\n      return `${money(it.opening_balance)} @ ${pct(it.annual_return)}${\n        it.monthly_contribution ? ` · +${money(it.monthly_contribution)}/mo` : ""}`;\n    case "strategies":\n      return `${it.debt_strategy} · ${pct(it.surplus_to_debt)} to debt`;\n    case "assumptions":\n      return [\n        it.inflation != null ? `inflation ${pct(it.inflation)}` : null,\n        it.cash_return != null ? `cash ${pct(it.cash_return)}` : null,\n      ].filter(Boolean).join(" · ");\n    case "events":\n      return `${money(it.amount)} · ${it.kind.replace(/_/g, " ")}`;\n    default:\n      return "";\n  }\n}\n\nfunction changeText(c) {\n  return Object.entries(c)\n    .filter(([k]) => k !== "month")\n    .map(([k, v]) => `${k.replace(/_/g, " ")} ${fieldValue(k, v)}`)\n    .join(", ");\n}\n\n// --- form conversions ----------------------------------------------------------\n\nfunction parseField(field, raw) {\n  if (field.t === "bool") return raw;\n  if (field.t === "list") {\n    return raw.split(",").map((s) => s.trim()).filter(Boolean);\n  }\n  const text = String(raw).trim();\n  if (text === "") return field.opt ? null : "";\n  if (field.t === "pct") return parseFloat((parseFloat(text) / 100).toFixed(8));\n  if (field.t === "money" || field.t === "number") return parseFloat(text);\n  return text;\n}\n\nfunction displayField(field, value) {\n  if (value === null || value === undefined) return field.t === "bool" ? false : "";\n  if (field.t === "bool") return Boolean(value);\n  if (field.t === "list") return (value || []).join(", ");\n  if (field.t === "pct") return String(Math.round(value * 1e6) / 1e4);\n  return String(value);\n}\n\n// --- DOM helper ----------------------------------------------------------------\n\nfunction h(tag, cls, text) {\n  const n = document.createElement(tag);\n  if (cls) n.className = cls;\n  if (text !== undefined && text !== null) n.textContent = text;\n  return n;\n}\n\n// Bar content: module name, then its values.\nfunction barContent(kind, item) {\n  const wrap = h("span", "fpb-bar-text");\n  wrap.append(h("span", "fpb-bar-name", item.label || item.id));\n  const val = valueText(kind, item);\n  if (val) wrap.append(h("span", "fpb-bar-val", val));\n  return wrap;\n}\n\n// --- widget --------------------------------------------------------------------\n\nexport function render({ model, el }) {\n  el.classList.add("fpb-timeline");\n  const errorBox = h("div", "fpb-error");\n  const body = h("div", "fpb-body");\n  el.append(errorBox, body);\n\n  const st = { plan: model.get("plan"), sel: null, localError: "" };\n\n  const setPlan = (plan) => {\n    st.plan = plan;\n    model.set("plan", plan);\n    model.save_changes();\n    draw();\n  };\n\n  const select = (kind, id) => {\n    st.sel = { kind, id };\n    draw();\n  };\n\n  const draw = () => {\n    body.replaceChildren(timelinePane(), panelPane());\n    errorBox.textContent = st.localError || model.get("error") || "";\n    errorBox.classList.toggle("on", Boolean(st.localError || model.get("error")));\n  };\n\n  model.on("change:plan", () => {\n    st.plan = model.get("plan");\n    st.localError = "";\n    draw();\n  });\n  model.on("change:error", () => draw());\n\n  // --- timeline ----------------------------------------------------------\n\n  function timelinePane() {\n    const plan = st.plan;\n    const v = viewRange(plan);\n    const width = (v.hi - v.lo) * PX;\n    const pane = h("div", "fpb-pane");\n    const grid = h("div", "fpb-grid");\n    grid.style.width = `${LABEL_W + width}px`;\n    // Quarter guide lines, one per quarter start, aligned with the track origin.\n    grid.style.backgroundImage = "linear-gradient(to right, rgba(127,127,127,0.22) 1px, transparent 1px)";\n    grid.style.backgroundSize = `${3 * PX}px 100%`;\n    grid.style.backgroundRepeat = "repeat-x";\n    grid.style.backgroundPosition = `${LABEL_W}px 0`;\n\n    // Header: year row and quarter row\n    const head = h("div", "fpb-row fpb-head");\n    head.append(h("div", "fpb-label", "Quarter"));\n    const headTrack = h("div", "fpb-track");\n    headTrack.style.width = `${width}px`;\n    for (let i = v.lo; i < v.hi; i += 3) {\n      const q = h("div", "fpb-q", `Q${((i % 12) / 3) + 1}`);\n      q.style.left = `${(i - v.lo) * PX}px`;\n      q.style.width = `${3 * PX}px`;\n      headTrack.append(q);\n      if (i % 12 === 0) {\n        const y = h("div", "fpb-year", String(Math.floor(i / 12)));\n        y.style.left = `${(i - v.lo) * PX}px`;\n        headTrack.append(y);\n      }\n    }\n    head.append(headTrack);\n    grid.append(head);\n\n    // Eras: labels only, read-only\n    grid.append(sectionRow("Eras (labels only)"));\n    for (const era of plan.eras) {\n      const row = h("div", "fpb-row");\n      row.append(h("div", "fpb-label", era.label));\n      const track = h("div", "fpb-track");\n      track.style.width = `${width}px`;\n      const band = h("div", "fpb-band", era.label);\n      const end = era.end ? idx(era.end) : v.hi - 1;\n      band.style.left = `${(idx(era.start) - v.lo) * PX}px`;\n      band.style.width = `${(end - idx(era.start) + 1) * PX}px`;\n      track.append(band);\n      row.append(track);\n      grid.append(row);\n    }\n\n    for (const kind of Object.keys(KINDS)) {\n      const cfg = KINDS[kind];\n      const items = plan[kind] || [];\n      grid.append(sectionRow(cfg.title));\n      if (items.length === 0) {\n        grid.append(h("div", "fpb-empty", `No ${cfg.title.toLowerCase()}`));\n        continue;\n      }\n      for (const item of items) grid.append(itemRow(kind, cfg, item, v, width));\n    }\n\n    pane.append(grid);\n    return pane;\n  }\n\n  function sectionRow(title) {\n    const row = h("div", "fpb-section");\n    row.append(h("div", "fpb-label", title));\n    return row;\n  }\n\n  function itemRow(kind, cfg, item, v, width) {\n    const row = h("div", "fpb-row");\n    const isSel = st.sel && st.sel.kind === kind && st.sel.id === item.id;\n    const label = h("div", "fpb-label" + (isSel ? " sel" : ""), item.label || item.id);\n    label.title = item.id;\n    label.addEventListener("click", () => select(kind, item.id));\n    row.append(label);\n\n    const track = h("div", "fpb-track");\n    track.style.width = `${width}px`;\n\n    if (cfg.point) {\n      const m = h("div", `fpb-marker ${kind}${isSel ? " sel" : ""}`);\n      m.style.left = `${(idx(item.month) - v.lo) * PX - 4}px`;\n      m.title = `${item.label} at ${item.month}: ${valueText(kind, item)}`;\n      m.append(h("span", "fpb-marker-val", `${item.label} · ${valueText(kind, item)}`));\n      m.addEventListener("pointerdown", (e) => startDrag(e, kind, item.id, "move", m, v));\n      track.append(m);\n    } else if (cfg.window) {\n      const s = idx(item.start);\n      const en = item.end ? idx(item.end) : v.hi - 1;\n      const b = h("div", `fpb-bar ${kind}${item.end ? "" : " open"}${isSel ? " sel" : ""}`);\n      b.append(barContent(kind, item));\n      b.style.left = `${(s - v.lo) * PX}px`;\n      b.style.width = `${(en - s + 1) * PX}px`;\n      b.title = `${item.label}: ${item.start} to ${item.end || "open-ended"}\\n${valueText(kind, item)}`;\n      b.addEventListener("pointerdown", (e) => startDrag(e, kind, item.id, "move", b, v));\n      const hl = h("div", "fpb-handle l");\n      hl.addEventListener("pointerdown", (e) => startDrag(e, kind, item.id, "l", b, v));\n      const hr = h("div", "fpb-handle r");\n      hr.addEventListener("pointerdown", (e) => startDrag(e, kind, item.id, "r", b, v));\n      b.append(hl, hr);\n      track.append(b);\n    } else if (cfg.account) {\n      const s = idx(item.start);\n      const b = h("div", `fpb-bar account ${kind}${isSel ? " sel" : ""}`);\n      b.append(barContent(kind, item));\n      b.style.left = `${(s - v.lo) * PX}px`;\n      b.style.width = `${(v.hi - s) * PX}px`;\n      b.title = `${item.label}: opens ${item.start}\\n${valueText(kind, item)}`;\n      b.addEventListener("pointerdown", (e) => startDrag(e, kind, item.id, "move", b, v));\n      track.append(b);\n      for (const c of item.changes || []) {\n        const tick = h("div", "fpb-change");\n        tick.style.left = `${(idx(c.month) - v.lo) * PX - 1}px`;\n        tick.title = `change at ${c.month}: ${changeText(c)}`;\n        track.append(tick);\n      }\n    }\n    row.append(track);\n    return row;\n  }\n\n  // Drag: move shifts the whole module, l/r move one edge. The bar snaps to quarter\n  // boundaries while dragging and commits on release. A release where nothing\n  // changed counts as a click and selects the module.\n  function startDrag(e, kind, id, mode, elem, v) {\n    if (e.button !== 0) return;\n    e.preventDefault();\n    e.stopPropagation();\n    const cfg = KINDS[kind];\n    const item = findItem(st.plan, kind, id);\n    const s0 = cfg.point ? idx(item.month) : idx(item.start);\n    const e0 = cfg.window && item.end ? idx(item.end) : null;\n    const x0 = e.clientX;\n    let cur = { s: s0, en: e0 };\n\n    const place = (r) => {\n      if (cfg.point) {\n        elem.style.left = `${(r.s - v.lo) * PX - 4}px`;\n      } else if (cfg.window) {\n        const endI = r.en === null ? v.hi - 1 : r.en;\n        elem.style.left = `${(r.s - v.lo) * PX}px`;\n        elem.style.width = `${(endI - r.s + 1) * PX}px`;\n      } else {\n        elem.style.left = `${(r.s - v.lo) * PX}px`;\n      }\n    };\n\n    const onMove = (ev) => {\n      const dm = Math.round((ev.clientX - x0) / PX);\n      cur = snapSpan(kind, mode, s0, e0, dm);\n      place(cur);\n    };\n\n    const onUp = () => {\n      window.removeEventListener("pointermove", onMove);\n      window.removeEventListener("pointerup", onUp);\n      if (cur.s === s0 && cur.en === e0) {\n        select(kind, id);\n        return;\n      }\n      commitSpan(kind, id, cur);\n    };\n\n    window.addEventListener("pointermove", onMove);\n    window.addEventListener("pointerup", onUp);\n  }\n\n  function commitSpan(kind, id, r) {\n    const cfg = KINDS[kind];\n    const plan = structuredClone(st.plan);\n    const item = findItem(plan, kind, id);\n    if (cfg.point) {\n      item.month = fmt(r.s);\n    } else {\n      item.start = fmt(r.s);\n      if (r.en !== null && item.end) item.end = fmt(r.en);\n    }\n    st.sel = { kind, id };\n    setPlan(plan);\n  }\n\n  // --- parameter panel -----------------------------------------------------\n\n  function panelPane() {\n    const panel = h("div", "fpb-panel");\n    if (!st.sel) {\n      panel.append(h("p", "fpb-hint",\n        "Drag a bar to move it. Drag its edges to change its length. Bars snap to quarters. Click a module to edit its parameters."));\n      return panel;\n    }\n    const cfg = KINDS[st.sel.kind];\n    const item = findItem(st.plan, st.sel.kind, st.sel.id);\n    if (!item) {\n      st.sel = null;\n      panel.append(h("p", "fpb-hint", "Select a module."));\n      return panel;\n    }\n    panel.append(h("h3", "", `${cfg.title}: ${item.label || item.id}`));\n    panel.append(h("div", "fpb-id", item.id));\n\n    const timing = [];\n    if (cfg.window) {\n      timing.push({ k: "start", t: "month" }, { k: "end", t: "month", opt: true });\n    } else if (cfg.account) {\n      timing.push({ k: "start", t: "month" });\n    } else if (cfg.point) {\n      timing.push({ k: "month", t: "month" });\n    }\n    for (const f of [...timing, ...cfg.fields]) {\n      panel.append(fieldRow(f, item[f.k], (raw) => editField(f, raw)));\n    }\n    if (cfg.changes) panel.append(changesEditor(cfg, item));\n    return panel;\n  }\n\n  function editField(field, raw) {\n    const kind = st.sel.kind;\n    const id = st.sel.id;\n    const value = parseField(field, raw);\n    const blank = value === null || value === "";\n    if (field.t === "month" && !(blank && field.opt) && !/^\\d{4}-\\d{2}$/.test(value || "")) {\n      st.localError = `${field.k}: expected YYYY-MM`;\n      draw();\n      return;\n    }\n    const plan = structuredClone(st.plan);\n    const item = findItem(plan, kind, id);\n    item[field.k] = blank && field.opt ? null : value;\n    st.localError = "";\n    setPlan(plan);\n  }\n\n  function fieldRow(field, value, onCommit) {\n    const row = h("label", "fpb-field");\n    row.append(h("span", "", field.k.replace(/_/g, " ")));\n    let input;\n    if (field.t === "select") {\n      input = h("select");\n      for (const opt of field.options) {\n        const o = h("option", "", opt);\n        o.value = opt;\n        if (opt === value) o.selected = true;\n        input.append(o);\n      }\n      input.addEventListener("change", () => onCommit(input.value));\n    } else if (field.t === "bool") {\n      input = h("input");\n      input.type = "checkbox";\n      input.checked = Boolean(value);\n      input.addEventListener("change", () => onCommit(input.checked));\n    } else {\n      input = h("input");\n      input.type = "text";\n      if (field.t === "money" || field.t === "pct") input.inputMode = "decimal";\n      input.value = displayField(field, value);\n      input.addEventListener("change", () => onCommit(input.value));\n    }\n    row.append(input);\n    return row;\n  }\n\n  // Term changes (refinance, contribution changes) on debts and assets.\n  function changesEditor(cfg, item) {\n    const wrap = h("div", "fpb-changes");\n    wrap.append(h("h4", "", "Term changes"));\n    const fieldFor = (name) => ({ k: name, t: CHANGE_TYPES[name] });\n    (item.changes || []).forEach((c, i) => {\n      const box = h("div", "fpb-change-row");\n      const month = h("input");\n      month.type = "text";\n      month.value = c.month;\n      month.title = "month";\n      month.addEventListener("change", () => editChange(i, "month", month.value));\n      box.append(month);\n      for (const name of cfg.changes) {\n        const f = fieldFor(name);\n        const inp = h("input");\n        inp.type = "text";\n        inp.placeholder = name.replace(/_/g, " ");\n        inp.title = `${name} (blank = unchanged)`;\n        inp.value = c[name] === undefined ? "" : displayField(f, c[name]);\n        inp.addEventListener("change", () => editChange(i, name, inp.value, f));\n        box.append(inp);\n      }\n      const rm = h("button", "", "remove");\n      rm.addEventListener("click", () => removeChange(i));\n      box.append(rm);\n      wrap.append(box);\n    });\n    const add = h("button", "fpb-add", "Add term change");\n    add.addEventListener("click", () => addChange(cfg, item));\n    wrap.append(add);\n    return wrap;\n  }\n\n  function editChange(i, key, raw, field) {\n    const plan = structuredClone(st.plan);\n    const item = findItem(plan, st.sel.kind, st.sel.id);\n    const change = item.changes[i];\n    if (key === "month") {\n      if (!/^\\d{4}-\\d{2}$/.test(String(raw).trim())) {\n        st.localError = "change month: expected YYYY-MM";\n        draw();\n        return;\n      }\n      change.month = String(raw).trim();\n    } else {\n      const value = parseField(field || { t: "money", opt: true }, raw);\n      if (value === null || value === "") delete change[key];\n      else change[key] = value;\n    }\n    setPlan(plan);\n  }\n\n  function addChange(cfg, item) {\n    const plan = structuredClone(st.plan);\n    const target = findItem(plan, st.sel.kind, st.sel.id);\n    const month = fmt(idx(target.start) + 12);\n    const first = cfg.changes[0];\n    target.changes = [...(target.changes || []), { month, [first]: item[first] }];\n    setPlan(plan);\n  }\n\n  function removeChange(i) {\n    const plan = structuredClone(st.plan);\n    const target = findItem(plan, st.sel.kind, st.sel.id);\n    target.changes.splice(i, 1);\n    setPlan(plan);\n  }\n\n  draw();\n}\n\nexport default { render };\n'

TIMELINE_CSS = '/* Plan timeline. Colors use currentColor and translucent fills so it reads in light and dark themes. */\n.fpb-timeline { font: 13px/1.4 system-ui, sans-serif; color: inherit; display: flex; flex-direction: column; gap: 8px; }\n.fpb-timeline .fpb-error { display: none; padding: 6px 10px; border-radius: 6px; background: rgba(220, 38, 38, 0.15); color: #dc2626; white-space: pre-wrap; }\n.fpb-timeline .fpb-error.on { display: block; }\n.fpb-body { display: flex; gap: 12px; align-items: flex-start; }\n.fpb-pane { flex: 1 1 auto; min-width: 0; overflow-x: auto; border: 1px solid rgba(127, 127, 127, 0.3); border-radius: 6px; }\n.fpb-grid { position: relative; }\n.fpb-row, .fpb-section { display: flex; height: 28px; align-items: stretch; border-bottom: 1px solid rgba(127, 127, 127, 0.15); }\n.fpb-section { height: 22px; background: rgba(127, 127, 127, 0.08); font-weight: 600; font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; align-items: center; }\n.fpb-head { height: 38px; font-size: 11px; }\n.fpb-head .fpb-track { height: 38px; }\n.fpb-q { position: absolute; top: 18px; height: 18px; line-height: 18px; text-align: center; font-size: 10px; opacity: 0.75; box-sizing: border-box; }\n.fpb-year { position: absolute; top: 0; height: 18px; line-height: 18px; padding-left: 4px; font-size: 11px; font-weight: 600; border-left: 1px solid rgba(127, 127, 127, 0.5); box-sizing: border-box; }\n.fpb-section > .fpb-label { background: inherit; }\n.fpb-bar-text { display: inline-flex; gap: 6px; align-items: baseline; }\n.fpb-bar-val { opacity: 0.9; font-size: 10px; }\n.fpb-marker-val { position: absolute; left: 12px; top: 0; white-space: nowrap; font-size: 11px; line-height: 16px; pointer-events: none; }\n.fpb-label { position: sticky; left: 0; z-index: 2; flex: 0 0 240px; width: 240px; padding: 4px 8px; background: Canvas; border-right: 1px solid rgba(127, 127, 127, 0.3); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; cursor: pointer; box-sizing: border-box; }\n.fpb-label.sel { font-weight: 700; text-decoration: underline; }\n.fpb-track { position: relative; flex: 0 0 auto; }\n.fpb-band { position: absolute; top: 3px; bottom: 3px; border-radius: 4px; background: rgba(59, 130, 246, 0.12); font-size: 10px; padding: 2px 4px; overflow: hidden; white-space: nowrap; }\n.fpb-bar { position: absolute; top: 4px; bottom: 4px; border-radius: 4px; padding: 0 6px; font-size: 11px; line-height: 20px; overflow: hidden; white-space: nowrap; color: #fff; cursor: grab; user-select: none; box-sizing: border-box; min-width: 4px; }\n.fpb-bar.open { border-top-right-radius: 0; border-bottom-right-radius: 0; }\n.fpb-bar.incomes { background: #16a34a; }\n.fpb-bar.expenses { background: #ea580c; }\n.fpb-bar.strategies { background: #7c3aed; }\n.fpb-bar.assumptions { background: #0891b2; }\n.fpb-bar.debts { background: #dc2626; }\n.fpb-bar.assets { background: #2563eb; }\n.fpb-bar.account { opacity: 0.85; }\n.fpb-bar.sel { outline: 2px solid currentColor; outline-offset: 1px; }\n.fpb-handle { position: absolute; top: 0; bottom: 0; width: 6px; cursor: ew-resize; }\n.fpb-handle.l { left: 0; }\n.fpb-handle.r { right: 0; }\n.fpb-marker { position: absolute; top: 6px; width: 8px; height: 16px; border-radius: 2px; background: #db2777; cursor: grab; }\n.fpb-marker.sel { outline: 2px solid currentColor; }\n.fpb-change { position: absolute; top: 2px; bottom: 2px; width: 2px; background: #f59e0b; pointer-events: none; }\n.fpb-empty { padding: 4px 10px; opacity: 0.6; font-style: italic; }\n.fpb-panel { flex: 0 0 340px; width: 340px; max-height: 620px; overflow-y: auto; padding: 8px 12px; border: 1px solid rgba(127, 127, 127, 0.3); border-radius: 6px; }\n.fpb-panel h3 { margin: 0 0 2px; font-size: 14px; }\n.fpb-panel h4 { margin: 12px 0 4px; font-size: 12px; }\n.fpb-id { font-family: ui-monospace, monospace; font-size: 11px; opacity: 0.6; margin-bottom: 8px; }\n.fpb-hint { opacity: 0.7; }\n.fpb-field { display: grid; grid-template-columns: 130px 1fr; gap: 6px; align-items: center; margin: 4px 0; }\n.fpb-field span { text-transform: capitalize; opacity: 0.85; }\n.fpb-field input, .fpb-field select, .fpb-change-row input { width: 100%; box-sizing: border-box; padding: 3px 5px; border: 1px solid rgba(127, 127, 127, 0.4); border-radius: 4px; background: transparent; color: inherit; font: inherit; }\n.fpb-field input[type="checkbox"] { width: auto; justify-self: start; }\n.fpb-change-row { display: grid; grid-template-columns: 78px 1fr 1fr auto; gap: 4px; margin: 4px 0; }\n.fpb-change-row button, .fpb-add { font: inherit; padding: 2px 6px; border: 1px solid rgba(127, 127, 127, 0.4); border-radius: 4px; background: transparent; color: inherit; cursor: pointer; }\n.fpb-add { margin-top: 6px; }\n'

TAX_TABLES = {'us_federal_2025.yaml': '# US federal individual income tax and payroll parameters, tax year 2025.\n# Source: IRS Rev. Proc. 2024-40 (brackets, SS wage base), One Big Beautiful Bill\n# Act (standard deduction), IRS Notice 2024-80 (401(k), IRA catch-up), Rev. Proc.\n# 2024-25 (HSA). Filing status keys: single, mfj.\ntax_year: 2025\nstd_deduction:\n  single: 15750\n  mfj: 31500\nbrackets:\n  single:\n    - [0, 0.10]\n    - [11925, 0.12]\n    - [48475, 0.22]\n    - [103350, 0.24]\n    - [197300, 0.32]\n    - [250525, 0.35]\n    - [626350, 0.37]\n  mfj:\n    - [0, 0.10]\n    - [23850, 0.12]\n    - [96950, 0.22]\n    - [206700, 0.24]\n    - [394600, 0.32]\n    - [501050, 0.35]\n    - [751600, 0.37]\nsocial_security:\n  rate: 0.062\n  wage_base: 176100\nmedicare:\n  rate: 0.0145\n  additional_rate: 0.009\n  additional_threshold:\n    single: 200000\n    mfj: 250000\nlimits:\n  "401k": 23500\n  "401k_catch_up": 7500\n  "ira": 7000\n  "ira_catch_up": 1000\n  "hsa_self": 4300\n  "hsa_family": 8550\n  "hsa_catch_up": 1000\ncatch_up_age:\n  "401k": 50\n  "ira": 50\n  "hsa": 55\n', 'us_federal_2026.yaml': '# US federal individual income tax and payroll parameters, tax year 2026.\n# Source: IRS Rev. Proc. 2025-32 (brackets, standard deduction, SS wage base),\n# IRS Notice 2025-67 (401(k), IRA), Rev. Proc. 2025-19 (HSA), SSA/IRS\n# Additional Medicare Tax (thresholds are statutory and not indexed).\n# Filing status keys: single, mfj. Head of household is not modeled.\ntax_year: 2026\nstd_deduction:\n  single: 16100\n  mfj: 32200\nbrackets:  # [threshold of taxable income, marginal rate]\n  single:\n    - [0, 0.10]\n    - [12400, 0.12]\n    - [50400, 0.22]\n    - [105700, 0.24]\n    - [201775, 0.32]\n    - [256225, 0.35]\n    - [640600, 0.37]\n  mfj:\n    - [0, 0.10]\n    - [24800, 0.12]\n    - [100800, 0.22]\n    - [211400, 0.24]\n    - [403550, 0.32]\n    - [512450, 0.35]\n    - [768700, 0.37]\nsocial_security:\n  rate: 0.062\n  wage_base: 184500\nmedicare:\n  rate: 0.0145\n  additional_rate: 0.009\n  additional_threshold:\n    single: 200000\n    mfj: 250000\nlimits:  # annual contribution limits, employee/individual\n  "401k": 24500\n  "401k_catch_up": 8000\n  "ira": 7500\n  "ira_catch_up": 1100\n  "hsa_self": 4400\n  "hsa_family": 8750\n  "hsa_catch_up": 1000\ncatch_up_age:\n  "401k": 50\n  "ira": 50\n  "hsa": 55\n'}

EXAMPLE_PLAN = '# Household plan for Brittany and Mark. Start is June 2023, the month of the mortgage.\n# All figures are placeholders except where noted. Replace balances with statements\n# using `python -m fpb.actuals template` and `python -m fpb.actuals import`.\nschema_version: 2\nname: Brittany and Mark\ncurrency: USD\nstart: "2023-06"\nbase_year: 2023\ninflation: 0.03\ncash_return: 0.0\nopening_cash: 0\n\npersons:\n  - id: brittany\n    name: Brittany\n    birth_year: 1991\n  - id: mark\n    name: Mark\n    birth_year: 1989\n\n# Eras are labels for the timeline and charts. They do not change any calculation.\neras:\n  - id: first_home\n    label: First home, mortgage years\n    start: "2023-06"\n    end: "2027-12"\n  - id: mid_career\n    label: Mid career\n    start: "2028-01"\n    end: "2033-12"\n  - id: family_peak\n    label: Family, refinanced, peak earning\n    start: "2034-01"\n\n# Pay-down rules. Each window selects the strategy for its months.\nstrategies:\n  - id: first_home_strategy\n    label: "First home: debt strategy"\n    start: "2023-06"\n    end: "2027-12"\n    debt_strategy: avalanche\n    surplus_to_debt: 0.4\n  - id: mid_career_strategy\n    label: "Mid career: debt strategy"\n    start: "2028-01"\n    end: "2033-12"\n    debt_strategy: snowball\n    surplus_to_debt: 0.4\n  - id: family_peak_strategy\n    label: "Family: debt strategy"\n    start: "2034-01"\n    debt_strategy: fixed\n    debt_priority: [credit_card, mortgage]\n\nassumptions:\n  - id: family_peak_assumptions\n    label: "Family: inflation"\n    start: "2034-01"\n    inflation: 0.025\n\nincomes:\n  - id: mark_salary_1\n    label: Mark salary\n    owner: mark\n    start: "2023-06"\n    end: "2027-12"\n    gross_annual: 98000\n    annual_raise: 0.03\n  - id: brittany_salary_1\n    label: Brittany salary\n    owner: brittany\n    start: "2023-06"\n    end: "2027-12"\n    gross_annual: 64000\n    annual_raise: 0.025\n  - id: mark_salary_2\n    label: Mark salary\n    owner: mark\n    start: "2028-01"\n    end: "2033-12"\n    gross_annual: 118000\n    annual_raise: 0.03\n  - id: brittany_salary_2\n    label: Brittany salary\n    owner: brittany\n    start: "2028-01"\n    end: "2033-12"\n    gross_annual: 72000\n    annual_raise: 0.025\n  - id: mark_salary_3\n    label: Mark salary\n    owner: mark\n    start: "2034-01"\n    gross_annual: 150000\n    annual_raise: 0.025\n  - id: brittany_salary_3\n    label: Brittany salary\n    owner: brittany\n    start: "2034-01"\n    gross_annual: 92000\n    annual_raise: 0.025\n\nexpenses:\n  - id: groceries_1\n    label: Groceries\n    category: food\n    start: "2023-06"\n    end: "2027-12"\n    monthly: 900\n  - id: utilities_1\n    label: Utilities and internet\n    category: housing\n    start: "2023-06"\n    end: "2027-12"\n    monthly: 260\n  - id: property_tax_1\n    label: Property tax (escrow)\n    category: housing\n    start: "2023-06"\n    end: "2027-12"\n    monthly: 450\n  - id: homeowners_insurance_1\n    label: Homeowners insurance\n    category: insurance\n    start: "2023-06"\n    end: "2027-12"\n    monthly: 180\n  - id: transport_1\n    label: Car insurance, fuel, transit\n    category: transport\n    start: "2023-06"\n    end: "2027-12"\n    monthly: 350\n  - id: health_insurance_1\n    label: Health and other insurance\n    category: insurance\n    start: "2023-06"\n    end: "2027-12"\n    monthly: 240\n  - id: discretionary_1\n    label: Dining, subscriptions, misc\n    category: lifestyle\n    start: "2023-06"\n    end: "2027-12"\n    monthly: 1100\n  - id: groceries_2\n    label: Groceries\n    category: food\n    start: "2028-01"\n    end: "2033-12"\n    monthly: 1050\n  - id: utilities_2\n    label: Utilities and internet\n    category: housing\n    start: "2028-01"\n    end: "2033-12"\n    monthly: 340\n  - id: property_tax_2\n    label: Property tax (escrow)\n    category: housing\n    start: "2028-01"\n    end: "2033-12"\n    monthly: 450\n  - id: homeowners_insurance_2\n    label: Homeowners insurance\n    category: insurance\n    start: "2028-01"\n    end: "2033-12"\n    monthly: 180\n  - id: transport_2\n    label: Car insurance, fuel, transit\n    category: transport\n    start: "2028-01"\n    end: "2033-12"\n    monthly: 380\n  - id: health_insurance_2\n    label: Health and other insurance\n    category: insurance\n    start: "2028-01"\n    end: "2033-12"\n    monthly: 260\n  - id: discretionary_2\n    label: Dining, subscriptions, misc\n    category: lifestyle\n    start: "2028-01"\n    end: "2033-12"\n    monthly: 1200\n  - id: groceries_3\n    label: Groceries\n    category: food\n    start: "2034-01"\n    monthly: 1400\n  - id: childcare_3\n    label: Childcare\n    category: family\n    start: "2034-01"\n    monthly: 1800\n  - id: utilities_3\n    label: Utilities and internet\n    category: housing\n    start: "2034-01"\n    monthly: 360\n  - id: property_tax_3\n    label: Property tax (escrow)\n    category: housing\n    start: "2034-01"\n    monthly: 480\n  - id: homeowners_insurance_3\n    label: Homeowners insurance\n    category: insurance\n    start: "2034-01"\n    monthly: 190\n  - id: transport_3\n    label: Two cars, insurance, fuel\n    category: transport\n    start: "2034-01"\n    monthly: 620\n  - id: health_insurance_3\n    label: Health and other insurance\n    category: insurance\n    start: "2034-01"\n    monthly: 340\n  - id: discretionary_3\n    label: Dining, activities, misc\n    category: lifestyle\n    start: "2034-01"\n    monthly: 1500\n\ndebts:\n  - id: mortgage\n    label: Primary mortgage (30y fixed)\n    start: "2023-06"\n    opening_balance: 380000\n    apr: 0.0625\n    minimum_payment: 2340\n    convention: monthly_apr\n    changes:\n      # Refinance in 2034: new rate and payment, same account and balance.\n      - month: "2034-01"\n        apr: 0.0525\n        minimum_payment: 2250\n  - id: car_loan\n    label: Car loan\n    start: "2023-06"\n    opening_balance: 18000\n    apr: 0.069\n    minimum_payment: 360\n    convention: monthly_apr\n  - id: student_loan\n    label: Federal student loan\n    owner: mark\n    start: "2023-06"\n    opening_balance: 32000\n    apr: 0.055\n    minimum_payment: 345\n    convention: monthly_apr\n  - id: credit_card\n    label: Credit card\n    owner: brittany\n    start: "2023-06"\n    opening_balance: 4200\n    apr: 0.2499\n    minimum_payment: 105\n    convention: daily_apr\n\nassets:\n  - id: home\n    label: Home\n    account_type: real_estate\n    start: "2023-06"\n    opening_balance: 440000\n    annual_return: 0.03\n  - id: emergency_fund\n    label: High-yield savings\n    account_type: cash\n    start: "2023-06"\n    opening_balance: 15000\n    annual_return: 0.04\n    monthly_contribution: 300\n  - id: joint_brokerage\n    label: Joint brokerage\n    account_type: taxable\n    start: "2023-06"\n    opening_balance: 9000\n    annual_return: 0.045\n    monthly_contribution: 1200\n  - id: mark_401k\n    label: Mark 401(k)\n    owner: mark\n    account_type: traditional_401k\n    start: "2023-06"\n    opening_balance: 42000\n    annual_return: 0.065\n    monthly_contribution: 1000\n    changes:\n      - month: "2034-01"\n        monthly_contribution: 1500\n  - id: brittany_roth_ira\n    label: Brittany Roth IRA\n    owner: brittany\n    account_type: roth_ira\n    start: "2023-06"\n    opening_balance: 9000\n    annual_return: 0.065\n    monthly_contribution: 580\n  - id: college_fund\n    label: 529 college savings\n    account_type: taxable\n    start: "2034-01"\n    opening_balance: 0\n    annual_return: 0.06\n    monthly_contribution: 300\n\nevents:\n  - id: college_seed\n    label: Seed college fund from savings\n    month: "2034-01"\n    kind: lump_sum_asset_contribution\n    amount: 20000\n    target_id: college_fund\n'
